from flask import Flask, request, jsonify
from transformers import pipeline

app = Flask(__name__)

# Load the NER model
ner_pipeline = pipeline("ner", model="sagorsarker/mbert-ner-hrl")

# Define the entity types we want to extract
target_entity_types = ["PER", "LOC", "ORG", "DATE", "EVENT"]

@app.route('/extract_entities', methods=['POST'])
def extract_entities():
    data = request.get_json()
    text = data.get('text', '')

    if not text:
        return jsonify([])

    # Get NER results
    ner_results = ner_pipeline(text)

    # Process results to match our schema
    entities = []
    for entity in ner_results:
        entity_type = entity['entity'].split('-')[-1]  # Get the specific type (PER, LOC, ORG, etc.)

        # Map model's entity types to our target types
        if entity_type == "PER":
            mapped_type = "PERSON"
        elif entity_type == "LOC":
            mapped_type = "LOCATION"
        elif entity_type == "ORG":
            mapped_type = "ORGANIZATION"
        elif entity_type in ["DATE", "TIME"]:
            mapped_type = "DATE"
        else:
            continue  # Skip entities we don't want

        # Add to results if it's one of our target types
        if mapped_type in ["PERSON", "LOCATION", "ORGANIZATION", "DATE", "EVENT"]:
            entities.append({
                "text": entity['word'],
                "type": mapped_type
            })

    return jsonify(entities)

if __name__ == '__main__':
    app.run(debug=True)

