import json
import os
from openai import OpenAI

client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

def get_ner(text):
    response = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[
            {
                "role": "system",
                "content": """You are doing Nepali Named Entity Recognition (EverestNER).Extract entities of these types ONLY: Person, Location, Organization, Date, Event.Return a JSON array ONLY (no markdown, no code fences, no extra text).Schema: [{"text":"...","type":"Person|Location|Organization|Date|Event"}]Do NOT return [] unless you are confident there are no entities in the text."""
            },
            {
                "role": "user",
                "content": f"Text: {text}"
            }
        ],
        temperature=0.0,
    )
    return response.choices[0].message.content

def main():
    with open("input.txt", "r") as f:
        lines = f.readlines()

    with open("output.jsonl", "w") as f:
        for line in lines:
            line = line.strip()
            if line:
                ner = get_ner(line)
                f.write(json.dumps({"text": line, "ner": ner}, ensure_ascii=False) + "\n")

if __name__ == "__main__":
    main()

