CORS(app)

@app.route('/extract_entities', methods=['POST'])
def extract_entities():
    data = request.get_json()
    text = data.get('text', '')

    # Prepare the payload for the LLM API
    payload = {
        "model": "llama3.1",
        "messages": [
            {
                "role": "user",
                "content": f"""You are doing Nepali Named Entity Recognition (EverestNER).Extract entities of these types ONLY: Person, Location, Organization, Date, Event.Return a JSON array ONLY (no markdown, no code fences, no extra text).Schema: [{{"text":"...","type":"Person|Location|Organization|Date|Event"}}]Do NOT return [] unless you are confident there are no entities in the text.

Text: {text}
Output:"""
            }
        ],
        "stream": False
    }

    # Call the LLM API
    response = requests.post(
        "http://localhost:11434/api/chat",
        json=payload
    )

    if response.status_code == 200:
        try:
            # Extract the JSON response from the LLM's output
            llm_response = response.json()
            entities_json = llm_response['message']['content'].strip()

            # Parse the JSON string into a Python list
            entities = json.loads(entities_json)
            return jsonify(entities)
        except json.JSONDecodeError:
            return jsonify([{"error": "Failed to parse LLM response"}]), 500
    else:
        return jsonify([{"error": "Failed to get response from LLM"}]), 500

if __name__ == '__main__':
    app.run(debug=True)

