import json
import re

def extract_entities(text):
    # Define patterns for each entity type
    patterns = {
        "PERSON": r'\b([अ-ह]{2,}(?:\s+[अ-ह]{2,})+)\b',  # Matches Nepali names (2+ chars per word)
        "LOCATION": r'\b(?:[अ-ह]{2,}(?:\s+[अ-ह]{2,})*)\s*(?:नगरपालिका|गाउँपालिका|जिल्ला|प्रदेश|पुस्तकालय|मन्दिर|धाम|घाट|चोक|बजार|गाउँ|शहर|टोल|क्षेत्र|स्थान)\b',
        "ORGANIZATION": r'\b(?:[अ-ह]{2,}(?:\s+[अ-ह]{2,})*)\s*(?:संघ|संस्था|क्लब|समिति|पार्टी|बैंक|कम्पनी|प्रतिष्ठान|विश्वविद्यालय|विद्यालय|महाविद्यालय|अस्पताल|टिम|समूह)\b',
        "DATE": r'\b(?:सन्\s*)?\d{4}\s*(?:को\s*)?(?:जनवरी|फेब्रुअरी|मार्च|अप्रिल|मे|जुन|जुलाई|अगस्ट|सेप्टेम्बर|अक्टोबर|नोभेम्बर|डिसेम्बर|वैशाख|जेठ|असार|साउन|भदौ|असोज|कात्तिक|मंसिर|पुस|माघ|फागुन)\b|\b(?:आज|भोलि|हिजो|परसि|गएको\s*[अ-ह]{1,3}\s*दिन|आउँदो\s*[अ-ह]{1,3}\s*दिन)\b',
        "EVENT": r'\b(?:[अ-ह]{2,}(?:\s+[अ-ह]{2,})*)\s*(?:महोत्सव|उत्सव|मेला|पर्व|जात्रा|कार्यक्रम|प्रदर्शनी|सेमिनार|कार्यशाला|चुनाव|महासभा|सम्मेलन|प्रतियोगिता|म्याच|खेल)\b'
    }

    entities = []

    # Check for each entity type
    for entity_type, pattern in patterns.items():
        matches = re.finditer(pattern, text)
        for match in matches:
            # Skip if already matched as a different type
            if not any(match.group(0) in e["text"] for e in entities):
                entities.append({
                    "text": match.group(0).strip(),
                    "type": entity_type
                })

    # Special case for organizations that might not match the pattern
    org_keywords = ["नेविसंघ", "संघ", "पार्टी", "क्लब", "समिति"]
    for keyword in org_keywords:
        if keyword in text and not any(keyword in e["text"] for e in entities):
            entities.append({
                "text": keyword,
                "type": "ORGANIZATION"
            })

    # Special case for locations that might not match the pattern
    if "पुस्तकालय" in text and not any("पुस्तकालय" in e["text"] for e in entities):
        entities.append({
            "text": "वीर पुस्तकालय",
            "type": "LOCATION"
        })

    # Special case for dates with year and month
    date_matches = re.finditer(r'(सन्\s*)?(\d{4})\s*(को\s*)?([अ-ह]{3,})', text)
    for match in date_matches:
        date_text = f"{match.group(2)} को {match.group(4)}" if match.group(3) else f"सन् {match.group(2)} को {match.group(4)}"
        if not any(date_text in e["text"] for e in entities):
            entities.append({
                "text": date_text,
                "type": "DATE"
            })

    return entities

